import{_ as i,y as n,a as l,o as p,a2 as o,g as t,I as r,D as a}from"./chunks/framework.DCcmcJcL.js";const b=JSON.parse('{"title":"Customer Group Pricing","description":"","frontmatter":{},"headers":[],"relativePath":"customer/customer-group-price.md","filePath":"customer/customer-group-price.md","lastUpdated":1789441803000}'),u={name:"customer/customer-group-price.md"};function h(d,e,c,g,m,f){const s=n("ImagePopup");return p(),l("div",null,[e[7]||(e[7]=o('<h1 id="customer-group-pricing" tabindex="-1">Customer Group Pricing <a class="header-anchor" href="#customer-group-pricing" aria-label="Permalink to &quot;Customer Group Pricing&quot;">​</a></h1><p>Customer group pricing gives a product lower prices for a customer group, for larger quantities, or for both. Use it for trade prices, such as a lower price for your <strong>Wholesale</strong> group, and for tier prices that reward shoppers who buy more. You set group prices on the product, in the <strong>Customer Group Price</strong> block of its <strong>Price</strong> section.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Create the customer group and move the customers into it, or use one of the default groups. See <a href="./customer-group.html">Customer Groups</a>.</li><li>The product needs a <strong>Price</strong> section. Simple, virtual, downloadable and booking products have one. Configurable, grouped and bundle products don&#39;t, because their price comes from the products they contain. See <a href="./../product-types/products.html#price">Products</a>.</li></ul><h2 id="add-a-group-price" tabindex="-1">Add a group price <a class="header-anchor" href="#add-a-group-price" aria-label="Permalink to &quot;Add a group price&quot;">​</a></h2>',5)),t("ol",null,[e[2]||(e[2]=t("li",null,[t("p",null,[r("Go to "),t("strong",null,"Catalog >> Products"),r(".")])],-1)),e[3]||(e[3]=t("li",null,[t("p",null,[r("Click "),t("strong",null,"Edit"),r(" (the arrow) on the product's row.")])],-1)),t("li",null,[e[0]||(e[0]=t("p",null,[r("Scroll to the "),t("strong",null,"Customer Group Price"),r(" block in the "),t("strong",null,"Price"),r(" section.")],-1)),a(s,{src:"/images/customer/customer-price.png",alt:"Customer Group Price block of a product with a Wholesale group price and the Add New link"})]),e[4]||(e[4]=o("<li><p>Click <strong>Add New</strong>. The <strong>Create Customer Group Price</strong> dialog opens.</p></li><li><p>Choose the <strong>Customer Group</strong>, or <strong>All Groups</strong> for every shopper, guests included.</p></li><li><p>Enter the <strong>Minimum Qty</strong>, the quantity the price starts at. Enter <strong>1</strong> for a price that applies to any quantity.</p></li><li><p>Choose the <strong>Price Type</strong>: <strong>Fixed</strong> for a set price per item, or <strong>Discount</strong> for a percentage off the product&#39;s <strong>Price</strong>.</p></li>",4)),t("li",null,[e[1]||(e[1]=t("p",null,[r("Enter the "),t("strong",null,"Price"),r(": the price per item for "),t("strong",null,"Fixed"),r(", or the percentage from 0 to 100 for "),t("strong",null,"Discount"),r(".")],-1)),a(s,{src:"/images/customer/group-price.png",alt:"Create Customer Group Price dialog with the Wholesale group, a minimum quantity of 10 and a 15 percent discount"})]),e[5]||(e[5]=t("li",null,[t("p",null,[r("Click "),t("strong",null,"Save"),r(". The group price is listed in the block with a summary, such as "),t("strong",null,"For 10 Qty at discount of 15"),r(".")])],-1)),e[6]||(e[6]=t("li",null,[t("p",null,[r("Click "),t("strong",null,"Save Product"),r(".")])],-1))]),e[8]||(e[8]=o('<h3 id="nothing-is-saved-until-you-save-the-product" tabindex="-1">Nothing is saved until you save the product <a class="header-anchor" href="#nothing-is-saved-until-you-save-the-product" aria-label="Permalink to &quot;Nothing is saved until you save the product&quot;">​</a></h3><p><strong>Save</strong> in the dialog only adds the group price to the block. The product&#39;s group prices are saved when you click <strong>Save Product</strong>. If you leave the edit screen without saving the product, your changes are lost.</p><h2 id="change-or-remove-a-group-price" tabindex="-1">Change or remove a group price <a class="header-anchor" href="#change-or-remove-a-group-price" aria-label="Permalink to &quot;Change or remove a group price&quot;">​</a></h2><p>To change a group price:</p><ol><li>Click <strong>Edit</strong> on its row in the <strong>Customer Group Price</strong> block. The <strong>Update Customer Group Price</strong> dialog opens.</li><li>Change the fields.</li><li>Click <strong>Save</strong>.</li><li>Click <strong>Save Product</strong>.</li></ol><p>To remove a group price:</p><ol><li>Click <strong>Edit</strong> on its row.</li><li>Click <strong>Delete</strong> in the dialog.</li><li>Click <strong>Agree</strong> to confirm.</li><li>Click <strong>Save Product</strong>.</li></ol><h2 id="which-price-a-shopper-pays" tabindex="-1">Which price a shopper pays <a class="header-anchor" href="#which-price-a-shopper-pays" aria-label="Permalink to &quot;Which price a shopper pays&quot;">​</a></h2><p>Bagisto works out a shopper&#39;s price from the group prices that apply to them:</p><ul><li>Only the group prices for the shopper&#39;s group and for <strong>All Groups</strong> count. Shoppers who aren&#39;t signed in belong to the <strong>Guest</strong> group.</li><li>Of those, the group price with the highest <strong>Minimum Qty</strong> that the quantity reaches is used.</li><li>A <strong>Discount</strong> is taken off the product&#39;s regular <strong>Price</strong>. A <strong>Fixed</strong> price is used only when it&#39;s lower than the price the group prices below it give.</li><li>The shopper then pays the lowest of that price, the product&#39;s <strong>Special Price</strong> while it runs, and the price from any <a href="./../marketing/catalog-rules.html">catalog rule</a>.</li></ul><p>The product page shows the price of one item. In the cart, the price follows the quantity in the cart.</p><h2 id="what-shoppers-see" tabindex="-1">What shoppers see <a class="header-anchor" href="#what-shoppers-see" aria-label="Permalink to &quot;What shoppers see&quot;">​</a></h2><p>On the product page, under the price, shoppers see one line for each group price with a <strong>Minimum Qty</strong> above 1 that applies to them, such as <em>Buy 10 for $102.00 each and save 15.00%</em>. The saving is worked out from the product&#39;s regular price. Group prices with a <strong>Minimum Qty</strong> of 1 aren&#39;t listed: they change the price shown instead.</p><h2 id="example-trade-and-bulk-prices" tabindex="-1">Example: trade and bulk prices <a class="header-anchor" href="#example-trade-and-bulk-prices" aria-label="Permalink to &quot;Example: trade and bulk prices&quot;">​</a></h2><p>A product has a <strong>Price</strong> of $120.00 and these group prices:</p><table tabindex="0"><thead><tr><th>Customer Group</th><th>Minimum Qty</th><th>Price Type</th><th>Price</th></tr></thead><tbody><tr><td><strong>All Groups</strong></td><td>5</td><td><strong>Discount</strong></td><td>10</td></tr><tr><td><strong>Wholesale</strong></td><td>10</td><td><strong>Discount</strong></td><td>15</td></tr><tr><td><strong>Wholesale</strong></td><td>20</td><td><strong>Fixed</strong></td><td>90</td></tr></tbody></table><p>The price of one item then depends on the shopper and the quantity:</p><table tabindex="0"><thead><tr><th>Quantity</th><th>Guest or General customer</th><th>Wholesale customer</th></tr></thead><tbody><tr><td>1 to 4</td><td>$120.00</td><td>$120.00</td></tr><tr><td>5 to 9</td><td>$108.00</td><td>$108.00</td></tr><tr><td>10 to 19</td><td>$108.00</td><td>$102.00</td></tr><tr><td>20 or more</td><td>$108.00</td><td>$90.00</td></tr></tbody></table><p>On the product page, a guest or a General customer sees <em>Buy 5 for $108.00 each and save 10.00%</em>. A Wholesale customer sees three lines:</p><ul><li><em>Buy 5 for $108.00 each and save 10.00%</em></li><li><em>Buy 10 for $102.00 each and save 15.00%</em></li><li><em>Buy 20 for $90.00 each and save 25.00%</em></li></ul>',20))])}const P=i(u,[["render",h]]);export{b as __pageData,P as default};
